const p = $input.item.json;
if (p.error) throw new Error('[CAROUSEL] API Graph error: ' + JSON.stringify(p.error));
const firstChild = p.children?.data?.[0] || null;
if (!firstChild) throw new Error('[CAROUSEL] Nenhum filho retornado para post_id 18066040568539014');
let coverSourceUrl = null;
let coverStrategy;
if (firstChild.media_type === 'VIDEO') {
  coverSourceUrl = firstChild.thumbnail_url || null;
  coverStrategy = 'CAROUSEL → filho[0] VIDEO → thumbnail_url do filho';
  if (!coverSourceUrl) throw new Error('[CAROUSEL] Filho[0] é VIDEO mas não tem thumbnail_url');
} else {
  coverSourceUrl = firstChild.media_url || null;
  coverStrategy = 'CAROUSEL → filho[0] ' + firstChild.media_type + ' → media_url do filho';
  if (!coverSourceUrl) throw new Error('[CAROUSEL] Filho[0] IMAGE/CAROUSEL sem media_url');
}
return { json: {
  post_id:          '18066040568539014',
  username:         'eduardocristianoriginal',
  media_type:       p.media_type,
  cover_source_url: coverSourceUrl,
  cover_strategy:   coverStrategy,
  total_filhos:     p.children?.data?.length || 0,
  filho0_tipo:      firstChild.media_type
}};

