const prep   = $('Preparar Download IMAGE').item.json;
const item   = $input.item;
if (item.json?.error) throw new Error('[IMAGE] Download falhou: ' + JSON.stringify(item.json.error));
const binary = item.binary?.data;
if (!binary) throw new Error('[IMAGE] Download não retornou dados binários');
const mime = (binary.mimeType || '').toLowerCase();
const MIMES_ACEITOS = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif' };
const ext = MIMES_ACEITOS[mime];
if (!ext) throw new Error('[IMAGE] MIME não aceito: ' + mime + ' — aceitos: image/jpeg, image/png, image/webp, image/gif');
// Medir tamanho real: binary.data é string base64 em n8n Code nodes
const size = Buffer.isBuffer(binary.data)
  ? binary.data.length
  : Buffer.byteLength(binary.data, 'base64');
const MAX = 5 * 1024 * 1024;
if (size > MAX) throw new Error('[IMAGE] Arquivo muito grande: ' + size + ' bytes (limite 5 MB)');
const storagePath = prep.username + '/' + prep.post_id + '.' + ext;
return {
  json: {
    post_id:          prep.post_id,
    username:         prep.username,
    media_type:       prep.media_type,
    cover_strategy:   prep.cover_strategy,
    mime_type:        mime,
    ext:              ext,
    file_size_bytes:  size,
    storage_path:     storagePath,
    upload_url:       $('Config').item.json.SUPABASE_URL + '/storage/v1/object/instagram-covers/' + storagePath,
    public_url:       $('Config').item.json.SUPABASE_URL + '/storage/v1/object/public/instagram-covers/' + storagePath,
    metricas_antes:   prep.metricas_antes
  },
  binary: { data: binary }
};

