const patch = $('Verificar PATCH IMAGE').item.json;
const head  = $input.item.json;
const pubStatus = head?.statusCode || head?.status || null;
const pubCT     = (head?.headers?.['content-type'] || head?.headers?.['Content-Type'] || '').toLowerCase();
const pubOk     = pubStatus === 200 && pubCT.startsWith('image/');
let statusFinal;
if (!patch.metricas_ok)         statusFinal = 'METRICAS_ALTERADAS';
else if (!pubOk)                statusFinal = 'URL_PUBLICA_INVALIDA';
else                            statusFinal = 'OK';
return { json: {
  post_id:              patch.post_id,
  username:             patch.username,
  media_type:           patch.media_type,
  cover_strategy:       patch.cover_strategy,
  status_final:         statusFinal,
  upload_ok:            true,
  patch_registros:      patch.patch_registros,
  cover_url_storage:    patch.patch_cover_url,
  cover_synced_at:      patch.patch_synced_at,
  url_publica_ok:       pubOk,
  url_publica_status:   pubStatus,
  url_publica_ct:       pubCT || null,
  mime_type:            patch.mime_type,
  file_size_bytes:      patch.file_size_bytes,
  metricas_ok:          patch.metricas_ok,
  metricas_divergentes: patch.metricas_divergentes
}};

