const items = $input.all();
// Guarda: se menos de 3 pipelines chegaram, uma falha de Download/Validar
// interrompeu aquele pipeline antes do Merge — reportar como falha explícita.
if (items.length !== 3) {
  return [{ json: {
    poc_summary: {
      total:           items.length,
      esperado:        3,
      ok:              0,
      falhou:          3,
      metricas_ok:     false,
      resultado_geral: 'REPROVADO — apenas ' + items.length + '/3 pipelines chegaram ao Merge; verificar erro nos nós Download/Validar do pipeline faltante'
    },
    detalhes: items.map(i => i.json),
    _nota: 'Pipelines faltantes falharam antes do Guard de Upload (Download, Validar ou API). Inspecionar execução dos nós Buscar, Analisar ou Validar Download.'
  }}];
}
const ok     = items.filter(i => i.json.status_final === 'OK').length;
const falhas = items.filter(i => i.json.status_final !== 'OK');
const todosMet = items.every(i => i.json.metricas_ok === true);
const resultado = ok === 3 && todosMet
  ? 'APROVADO — 3/3 capas persistidas com métricas intactas'
  : 'REPROVADO — ' + (3 - ok) + ' pipeline(s) com falha';
const detalhes = items.map(i => {
  const j = i.json;
  return {
    post_id:              j.post_id,
    username:             j.username,
    media_type:           j.media_type,
    cover_strategy:       j.cover_strategy,
    status_final:         j.status_final,
    upload_ok:            j.upload_ok,
    patch_registros:      j.patch_registros,
    cover_url_storage:    j.cover_url_storage,
    cover_synced_at:      j.cover_synced_at,
    url_publica_ok:       j.url_publica_ok,
    url_publica_status:   j.url_publica_status,
    url_publica_ct:       j.url_publica_ct,
    mime_type:            j.mime_type,
    file_size_bytes:      j.file_size_bytes,
    metricas_ok:          j.metricas_ok,
    metricas_divergentes: j.metricas_divergentes,
    erro:                 j.erro || null
  };
});
// runOnceForAllItems: retornar array de itens
return [{ json: {
  poc_summary: {
    total:           items.length,
    ok:              ok,
    falhou:          items.length - ok,
    metricas_ok:     todosMet,
    resultado_geral: resultado
  },
  detalhes: detalhes,
  _nota: 'cover_url_storage contém a URL permanente do Supabase Storage. URLs brutas da Meta CDN não aparecem neste relatório.'
}}];
